// Launch Params: the launch row is the whole contract. Client link resolves the base, the
// Storeleads filter fields on the row shape the pull, Max companies is the spend cap, Tag is
// stamped on every row landed. Any missing piece stops the run here, before a single paid call.
//
// The contacts pull this door fires afterwards is NOT hardcoded (ruled 2026-09-02). Tiers,
// Departments and Roles are read off this same launch row and handed to Waterfall Contacts by
// Fire Contacts, and Max companies serves as its cap too: the row's own spend cap bounds both
// what this door lands and what the contacts pull then works. Blank means today's behaviour,
// the full waterfall with no department or role filter. Tiers falls back to the older Sources
// multi-select while launch rows still carry it.
const rec=$('Fetch Launch Record').first().json;
const f=rec.fields||{};
const cf=($('Resolve Base').first().json.fields)||{};
const base=((cf['Clayroots Base ID']||'')+'').trim();
const clientRecId=((f['Client']||[])[0])||'';
const tag=((f['Tag']||'')+'').trim();
const maxCompanies=parseInt(f['Max companies'],10);
if(!clientRecId){ throw new Error('Launch record '+rec.id+' has no Client link. Nothing was pulled.'); }
if(!/^app[A-Za-z0-9]{14}$/.test(base)){ throw new Error('Client on launch record '+rec.id+' has no valid Clayroots Base ID. Nothing was pulled.'); }
if(!Number.isFinite(maxCompanies)||maxCompanies<1){ throw new Error('Launch record '+rec.id+' has no Max companies. It is the Storeleads spend cap and is required. Nothing was pulled.'); }
const list=(v)=>Array.isArray(v)?v.map(x=>String(x).trim()).filter(Boolean):((v==null||v==='')?[]:String(v).split(',').map(s=>s.trim()).filter(Boolean));
const text=(v)=>(v==null?'':String(v)).trim();
const visits=f['Min monthly visits'];
return [{ json: {
  base: base,
  clientRecId: clientRecId,
  tag: tag,
  country: list(f['Country']),
  platforms: list(f['Platforms']),
  plan: list(f['Plan']),
  monthlyRevenue: list(f['Monthly revenue']),
  employees: list(f['Employees']),
  productCount: list(f['Product count']),
  storeAge: list(f['Store age']),
  minMonthlyVisits: (visits==null||visits==='')?null:Number(visits),
  category: text(f['Category']),
  technologies: text(f['Technologies']),
  mustHaveAppIds: text(f['Must-have app IDs']),
  maxCompanies: maxCompanies,
  contactsTiers: text(f['Tiers'])||(list(f['Sources']).length?'':'ContaGen -> Supersoniq -> AI-Ark'),
  contactsSources: list(f['Sources']),
  contactsDepartments: list(f['Departments']),
  contactsRoles: list(f['Roles']),
  contactsMaxCompanies: maxCompanies,
  _launchRecordId: rec.id,
  startedAt: new Date().toISOString()
} }];

// Build SL Query: the launch row's filters become one Storeleads pull query per provider x
// country. Max companies (already validated by Launch Params) is the spend cap the loop
// enforces; the batch pulls only what is still short of it.
const lp = $('Launch Params').first().json;
const CMAP = {'United States':'US','United Kingdom':'GB','Canada':'CA','Australia':'AU','Ireland':'IE','Israel':'IL','Germany':'DE','France':'FR','Netherlands':'NL','usa':'US','us':'US','uk':'GB','england':'GB'};
const asArr=(v)=>{ if(v===undefined||v===null||v==='')return[]; if(Array.isArray(v))return v.map(x=>String(x).trim()).filter(Boolean); return String(v).split(',').map(s=>s.trim()).filter(Boolean); };
const toCode=(x)=>{ const s=String(x).trim(); if(CMAP[s])return CMAP[s]; if(CMAP[s.toLowerCase()])return CMAP[s.toLowerCase()]; if(/^[A-Za-z]{2}$/.test(s))return s.toUpperCase(); return ''; };
const ccList = Array.from(new Set(asArr(lp.country).map(toCode).filter(Boolean)));
const ALLOWED = ['shopify','woocommerce','bigcommerce','wix','squarespace','magento'];
let selP = asArr(lp.platforms).map(s=>String(s).toLowerCase()).filter(s=>ALLOWED.includes(s));
const planTicked = asArr(lp.plan).includes('Shopify Plus');
if (planTicked) selP = ['shopify'];
const providers = selP.length ? Array.from(new Set(selP)) : ['all'];
const maxCompanies = parseInt(lp.maxCompanies, 10);
if (!Number.isFinite(maxCompanies) || maxCompanies < 1) { throw new Error('Max companies is missing or not a positive number. It is the Storeleads spend cap. Nothing was pulled.'); }
const baseFilters = { 'f:state': 'Active' };
if (planTicked) baseFilters['f:plan'] = 'Shopify Plus';
const envelope=(ticked, ORDER, MAP)=>{ const s=ticked.filter(b=>MAP[b]); if(!s.length) return [null,null]; const idxs=s.map(b=>ORDER.indexOf(b)).filter(i=>i>=0).sort((a,b)=>a-b); return [MAP[ORDER[idxs[0]]][0], MAP[ORDER[idxs[idxs.length-1]]][1]]; };
const REV_ORDER=['Under $10k','$10k-50k','$50k-100k','$100k-500k','$500k-1M','$1M+'];
const REV={'Under $10k':[null,1000000],'$10k-50k':[1000000,5000000],'$50k-100k':[5000000,10000000],'$100k-500k':[10000000,50000000],'$500k-1M':[50000000,100000000],'$1M+':[100000000,null]};
const rev=envelope(asArr(lp.monthlyRevenue),REV_ORDER,REV);
if(rev[0]!=null)baseFilters['f:ermin']=String(rev[0]); if(rev[1]!=null)baseFilters['f:ermax']=String(rev[1]);
const EMP_ORDER=['1-10','11-50','51-200','200+'];
const EMP={'1-10':[1,10],'11-50':[11,50],'51-200':[51,200],'200+':[200,null]};
const emp=envelope(asArr(lp.employees),EMP_ORDER,EMP);
if(emp[0]!=null)baseFilters['f:empcmin']=String(emp[0]); if(emp[1]!=null)baseFilters['f:empcmax']=String(emp[1]);
const PC_ORDER=['1-50','51-500','500+'];
const PC={'1-50':[1,50],'51-500':[51,500],'500+':[500,null]};
const pc=envelope(asArr(lp.productCount),PC_ORDER,PC);
if(pc[0]!=null)baseFilters['f:pcmin']=String(pc[0]); if(pc[1]!=null)baseFilters['f:pcmax']=String(pc[1]);
const iso=(d)=>d.toISOString().slice(0,19)+'Z';
const now=new Date();
const yearsAgo=(y)=>{ const d=new Date(now.getTime()); d.setUTCFullYear(d.getUTCFullYear()-y); return d; };
const AGE_ORDER=['Under 1 year','1-3 years','3+ years'];
const AGE={'Under 1 year':[0,1],'1-3 years':[1,3],'3+ years':[3,null]};
const ageTicked=asArr(lp.storeAge).filter(b=>AGE[b]);
if(ageTicked.length){ const aidx=ageTicked.map(b=>AGE_ORDER.indexOf(b)).filter(i=>i>=0).sort((a,b)=>a-b); const minAge=AGE[AGE_ORDER[aidx[0]]][0]; const maxAge=AGE[AGE_ORDER[aidx[aidx.length-1]]][1]; if(maxAge!=null)baseFilters['f:cratmin']=iso(yearsAgo(maxAge)); if(minAge>0)baseFilters['f:cratmax']=iso(yearsAgo(minAge)); }
const minVisits = parseInt(lp.minMonthlyVisits, 10);
if (Number.isFinite(minVisits) && minVisits > 0) baseFilters['f:evmin'] = String(minVisits);
const catList = asArr(lp.category);
if (catList.length) { baseFilters['f:cat'] = catList.join(','); baseFilters['f:cat:op'] = 'or'; }
const techList = asArr(lp.technologies);
if (techList.length) { baseFilters['f:tech'] = techList.join(','); baseFilters['f:tech:op'] = 'and'; }
const appIds = asArr(lp.mustHaveAppIds);
if (appIds.length) { baseFilters['f:an']=appIds.join(','); baseFilters['f:an:op']='and'; }
const fields = 'name,tld1,merchant_name,title,description,categories,country_code,city,administrative_area_level_1,estimated_sales,employee_count,rank,platform,state,plan,created_at,product_count,monthly_app_spend,apps,technologies,trustpilot,last_platform,last_platform_change_at,features,contact_info';
const cList = ccList.length ? ccList : [null];
const out=[];
for(const prov of providers){ for(const cc of cList){ const f = Object.assign({}, baseFilters); if(cc) f['f:cc']=cc; const pullQuery = Object.assign({}, f, { page_size: 50, sort: 'rank', fields }); out.push({ json: { _provider: prov, _country: cc||'ALL', countryCode: cc||'', _ccList: ccList, pullQuery, maxCompanies, providerCount: providers.length, countryCount: cList.length } }); } }
return out;

// Preflight: the helper's rows-less call (Insert domains to Clayroots), before the first
// metered Storeleads page. One item carrying only _meta, with keys = the row keys Process Batch
// (SL Batch Pull) writes: the helper's Check Columns refuses when the landing fields or the
// Storeleads declared extras are missing on Companies (they are register fields, never created
// here: scaffold the base with Extras = Storeleads), and creates any open key once for the run.
// The batches then call the same helper with rows and allowNew off.
const p=$('Launch Params').first().json;
const KEYS=['Domain','Company','Description','Industry Groups','Employees','Country','State','City','Public Emails','public_emails_clean','MX Provider','Plan','Revenue Est Monthly','Store Age Years','Product Count','App Spend Mo','Key Apps','Tech Stack','Trustpilot Rating','Trustpilot Reviews','Migrated From','Social Followers','Features'];
return [{ json: { _meta: { base: p.base, clientRecId: p.clientRecId, tag: p.tag||'', domainSource: 'Storeleads', allowNew: true, keys: KEYS } } }];

// Init Loop State: one static-data record carries the batch loop. Counters only; rows never
// cross the sub-workflow boundary. kept is the spend meter (rows prepared for the write,
// what the cap counts); upserted is what actually landed (record ids returned by the helper).
const qs = $('Build SL Query').all().map(i => ({ provider: i.json._provider, pullQuery: i.json.pullQuery }));
const cap = Number($('Build SL Query').first().json.maxCompanies);
if (!Number.isFinite(cap) || cap < 1) throw new Error('Loop cap missing: Max companies did not reach the loop. Nothing was pulled.');
const sd = $getWorkflowStaticData('global');
sd.slBatchState = { cap, qIndex: 0, cursor: '', batchNum: 0, retried: false, remaining: cap, totals: { pulled: 0, kept: 0, upserted: 0, withEmails: 0, failed: 0, skipped: 0, inactive: 0, duplicate: 0, dnc: 0 }, failReasons: [] };
return [{ json: { action: 'continue', qIndex: 0, cursor: '', remaining: cap, queries: qs } }];

// Loop Control: reads one batch summary, adds it to the running totals, and decides the next
// move: continue (next cursor or next query), retry once after Storeleads error pages, or
// done. A second round of error pages on the same cursor fails loud. Hard cap: 500 batches.
const res = $input.first().json;
const sd = $getWorkflowStaticData('global');
const st = sd.slBatchState;
if (!st) throw new Error('Loop state missing: Init Loop State did not run');
const queries = $('Init Loop State').first().json.queries || [];
st.batchNum = (st.batchNum || 0) + 1;
if (st.batchNum > 500) throw new Error('Storeleads batch loop hit the hard cap of 500 batches. Totals so far: pulled ' + st.totals.pulled + ', kept ' + st.totals.kept + ', upserted ' + st.totals.upserted + '. Last cursor: "' + st.cursor + '" (query ' + (st.qIndex + 1) + '/' + queries.length + ').');
if (res.errorPages && res.errorPages > 0) {
  if (st.retried) {
    throw new Error('Storeleads returned error pages twice for cursor "' + st.cursor + '" (provider ' + ((queries[st.qIndex] || {}).provider || '?') + ', query ' + (st.qIndex + 1) + '/' + queries.length + '). Totals so far: pulled ' + st.totals.pulled + ', kept ' + st.totals.kept + ', upserted ' + st.totals.upserted + '.');
  }
  st.retried = true;
  return [{ json: { action: 'retry', qIndex: st.qIndex, cursor: st.cursor, remaining: st.remaining } }];
}
st.retried = false;
const n = (k) => Number(res[k]) || 0;
st.totals.pulled += n('pulled');
st.totals.kept += n('kept');
st.totals.upserted += n('upserted');
st.totals.withEmails += n('withEmails');
st.totals.failed += n('failed');
st.totals.skipped += n('skipped');
st.totals.inactive += n('inactive');
st.totals.duplicate += n('duplicate');
st.totals.dnc = (st.totals.dnc || 0) + n('dnc');
st.failReasons = Array.isArray(st.failReasons) ? st.failReasons : [];
for (const x of (Array.isArray(res.failReasons) ? res.failReasons : [])) { if (st.failReasons.length < 5) st.failReasons.push(String(x)); }
st.remaining = Math.max(0, st.cap - st.totals.kept);
if (res.has_next_page && st.remaining > 0 && res.next_cursor) {
  st.cursor = String(res.next_cursor);
  return [{ json: { action: 'continue', qIndex: st.qIndex, cursor: st.cursor, remaining: st.remaining } }];
}
st.qIndex += 1;
st.cursor = '';
if (st.qIndex < queries.length && st.remaining > 0) {
  return [{ json: { action: 'continue', qIndex: st.qIndex, cursor: '', remaining: st.remaining } }];
}
return [{ json: Object.assign({ action: 'done' }, st.totals) }];

// Fire Contacts: one item in Waterfall Contacts' event shape (Event Row reads the launch-row
// keys), so the companies just landed get their people at once. Table Companies and View
// "Not Sourced" are structural, this door always sources what it just landed. Everything else
// comes off THIS door's own launch row (Launch Params read it): Tiers, Departments, Roles and
// Max companies pass straight through, the row's Max companies serving as the contacts cap too.
// Blank on the row means the full waterfall, no department filter, no role filter, which is what
// this door always did before 2026-09-02. Waterfall Contacts writes its own run-log row.
const p=$('Launch Params').first().json;
const out={ Client: [p.clientRecId], Table: 'Companies', View: 'Not Sourced', 'Max companies': p.contactsMaxCompanies, Departments: p.contactsDepartments||[], Roles: p.contactsRoles||[], Tag: p.tag||'' };
if(p.contactsTiers) out.Tiers=p.contactsTiers;
if((p.contactsSources||[]).length) out.Sources=p.contactsSources;
return [{ json: out }];

// Build Log: one row per run on the launch row, status computed from failed[], skips
// separated from errors, Client attached (a launched run serves exactly one client).
// Records Out is what the helper's upserts returned record ids for, never the pre-write count.
// The table, the columns created and the keys dropped come from the preflight call (Check
// Base); the batch totals from the loop state.
const p=$('Launch Params').first().json;
let cfg={}; try{ cfg=$('Check Base').first().json||{}; }catch(e){}
const sd=$getWorkflowStaticData('global');
const st=(sd.slBatchState)||{};
const t=Object.assign({ pulled:0, kept:0, upserted:0, withEmails:0, failed:0, skipped:0, inactive:0, duplicate:0, dnc:0 }, st.totals||{});
const failed=[];
for(const r of (st.failReasons||[])) failed.push({ name:'upsert', reason:String(r).slice(0,120) });
const errors=Number(t.failed)||0;
if(errors>failed.length) failed.push({ name:'upsert', reason:(errors-failed.length)+' more rows returned no record id' });
let fired=false; try{ fired=$('Fire Contacts').all().length>0; }catch(e){}
let queries=[]; try{ queries=$('Build SL Query').all().map(i=>i.json||{}); }catch(e){}
const providers=Array.from(new Set(queries.map(q=>q._provider).filter(Boolean)));
const countries=Array.from(new Set(queries.map(q=>q._country).filter(Boolean)));
const SKIP=new Set(['page_size','sort','fields','f:cc']);
const filters=Object.entries((queries[0]||{}).pullQuery||{}).filter(([k])=>!SKIP.has(k)).map(([k,v])=>k+'='+v).join(', ');
let dur=0; try{ dur=Math.max(0,Math.round(($now.toMillis()-new Date(p.startedAt).getTime())/1000)); }catch(e){}
const fmt=v=>Number(v||0).toLocaleString('en-US');
const tableName=cfg.tableName||'Companies';
const lines=[
  '**'+fmt(t.pulled)+' stores pulled, '+fmt(t.upserted)+' landed on '+tableName+'**',
  '',
  '**Source:** Storeleads, providers '+(providers.join(', ')||'all')+', countries '+(countries.join(', ')||'ALL')+', cap '+fmt(st.cap||p.maxCompanies),
  '**Filters:** '+(filters||'none'),
  '**Tag:** '+(p.tag||'none'),
  '',
  '**Funnel**',
  '- **Pulled:** '+fmt(t.pulled),
  '- **Kept (active, unique domain, under the cap):** '+fmt(t.kept),
  '- **Landed (record id returned):** '+fmt(t.upserted),
  '- **With public emails:** '+fmt(t.withEmails),
  '- **Without public emails:** '+fmt(Math.max(0,t.upserted-t.withEmails))
];
if(Array.isArray(cfg.createdColumns)&&cfg.createdColumns.length) lines.push('- **Columns created (open fields):** '+cfg.createdColumns.join(', '));
if(Array.isArray(cfg.droppedKeys)&&cfg.droppedKeys.length) lines.push('- **Keys dropped:** '+cfg.droppedKeys.map(d=>d.key+' ('+d.why+')').join(', '));
lines.push('', '**Contacts:** '+(fired?'Waterfall Contacts fired on view "Not Sourced" (all three sources, Max companies 5000); it writes its own row':'not fired, nothing landed'));
const skips=[]; if(t.skipped) skips.push(fmt(t.skipped)+' empty domain'); if(t.inactive) skips.push(fmt(t.inactive)+' inactive store'); if(t.duplicate) skips.push(fmt(t.duplicate)+' duplicate domain in the pull'); if(t.dnc) skips.push(fmt(t.dnc)+' on the DNC table');
if(skips.length) lines.push('', '**Skipped ('+skips.join(', ')+')**');
if(failed.length){ lines.push('', '**Failures**'); for(const f of failed.slice(0,10)) lines.push('- '+f.name+': '+f.reason); }
const log={
  'Automation':'Insert Storeleads domains to Clayroots',
  'Status': errors?'Succeeded with errors':'Succeeded',
  'Trigger':'form',
  'Errors': errors,
  'Run at': $now.toISO(),
  'Target': tableName+' ('+(cfg.tableId||'')+')',
  'Records In': t.pulled,
  'Records Out': t.upserted,
  'Duration s': dur,
  'Description': lines.join('\n'),
  'Execution Link':'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id,
  'Execution ID': String($execution.id),
  'Client': [p.clientRecId]
};
return [{ json: log }];
